title: use client
description: Learn how to use the use client directive to render a component on the client.
---

The `'use client'` directive declares an entry point for the components to be rendered on the **client side** and should be used when creating interactive user interfaces (UI) that require client-side JavaScript capabilities, such as state management, event handling, and access to browser APIs. This is a React feature.

> **Good to know:**
>
> You do not need to add the `'use client'` directive to every file that contains Client Components. You only need to add it to the files whose components you want to render directly within Server Components. The `'use client'` directive defines the client-server [boundary](https://nextjs.org/docs/app/building-your-application/rendering#network-boundary), and the components exported from such a file serve as entry points to the client.

## Usage

To declare an entry point for the Client Components, add the `'use client'` directive **at the top of the file**, before any imports:

```tsx filename="app/components/counter.tsx" highlight={1} switcher
'use client'

import { useState } from 'react'

export default function Counter() {
  const [count, setCount] = useState(0)

  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={() => setCount(count + 1)}>Increment</button>
    </div>
  )
}
```

```jsx filename="app/components/counter.js" highlight={1} switcher
'use client'

import { useState } from 'react'

export default function Counter() {
  const [count, setCount] = useState(0)

  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={() => setCount(count + 1)}>Increment</button>
    </div>
  )
}
```

When using the `'use client'` directive, the props of the Client Components must be [serializable](https://react.dev/reference/rsc/use-client#serializable-types). This means the props need to be in a format that React can serialize when sending data from the server to the client.

```tsx filename="app/components/counter.tsx" highlight={4} switcher
'use client'

export default function Counter({
  onClick /* ❌ Function is not serializable */,
}) {
  return (
    <div>
      <button onClick={onClick}>Increment</button>
    </div>
  )
}
```

```jsx filename="app/components/counter.js" highlight={4} switcher
'use client'

export default function Counter({
  onClick /* ❌ Function is not serializable */,
}) {
  return (
    <div>
      <button onClick={onClick}>Increment</button>
    </div>
  )
}
```

## Nesting Client Components within Server Components

Combining Server and Client Components allows you to build applications that are both performant and interactive:

1. **Server Components**: Use for static content, data fetching, and SEO-friendly elements.
2. **Client Components**: Use for interactive elements that require state, effects, or browser APIs.
3. **Component composition**: Nest Client Components within Server Components as needed for a clear separation of server and client logic.

In the following example:

- `Header` is a Server Component handling static content.
- `Counter` is a Client Component enabling interactivity within the page.

```tsx filename="app/page.tsx" highlight={2,8} switcher
import Header from './header'
import Counter from './counter' // This is a Client Component

export default function Page() {
  return (
    <div>
      <Header />
      <Counter />
    </div>
  )
}
```

```jsx filename="app/page.js" highlight={2,8} switcher
import Header from './header'
import Counter from './counter' // This is a Client Component

export default function Page() {
  return (
    <div>
      <Header />
      <Counter />
    </div>
  )
}
```

## Reference

See the [React documentation](https://react.dev/reference/rsc/use-client) for more information on `'use client'`.
"use client";

import { Suspense, useEffect, useMemo, useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";

import {
  Conversation,
  ConversationContent,
  ConversationScrollButton,
} from "@/components/ai-elements/conversation";
import { CockpitShell } from "@/components/cockpit/cockpit-shell";
import { IncidentHeader } from "@/components/cockpit/incident-header";
import { LiveCandidatePanel } from "@/components/cockpit/live-candidate-panel";
import {
  MessageComposer,
  type ComposerState,
} from "@/components/cockpit/message-composer";
import { PlanChecklist } from "@/components/cockpit/plan-checklist";
import { SessionSidebar } from "@/components/cockpit/session-sidebar";
import { useDevinCase } from "@/hooks/use-devin-case";
import { buildCockpitView } from "@/lib/live/cockpit-view";

const COMPOSER_STATE: ComposerState = {
  status: "disabled",
  reason: "Follow-up messaging is not connected yet.",
};

export function CockpitChat() {
  return (
    <Suspense fallback={null}>
      <DevinCockpit />
    </Suspense>
  );
}

function DevinCockpit() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const caseFromUrl = searchParams.get("case");
  const devin = useDevinCase(caseFromUrl);
  const { status, launch } = devin;
  const [candidatesOpen, setCandidatesOpen] = useState(true);
  const [message, setMessage] = useState("");
  const cockpitView = useMemo(
    () => buildCockpitView(devin.snapshot, devin.plan, devin.events),
    [devin.events, devin.plan, devin.snapshot],
  );

  useEffect(() => {
    if (caseFromUrl || status !== "idle") return;
    void launch().then((caseId) => {
      if (caseId) router.replace(`/chat?case=${encodeURIComponent(caseId)}`);
    });
  }, [caseFromUrl, launch, router, status]);

  async function startNewSession() {
    const caseId = await devin.launch();
    if (caseId) router.replace(`/chat?case=${encodeURIComponent(caseId)}`);
  }

  function selectSession(caseId: string) {
    router.replace(`/chat?case=${encodeURIComponent(caseId)}`, {
      scroll: false,
    });
  }

  const incident = devin.snapshot?.incident ?? null;
  const part = devin.snapshot?.part ?? null;

  return (
    <CockpitShell
      leftSidebar={
        <SessionSidebar
          sessions={devin.cases}
          activeCaseId={devin.caseId}
          launching={devin.status === "launching"}
          onSelectSession={selectSession}
          onNewSession={() => void startNewSession()}
        />
      }
      rightSidebar={
        candidatesOpen ? (
          <LiveCandidatePanel
            candidates={devin.candidates}
            supplierRecords={devin.snapshot?.supplier_records ?? []}
            onClose={() => setCandidatesOpen(false)}
          />
        ) : undefined
      }
    >
      <div className="grid h-full min-h-0 min-w-0 grid-rows-[auto_minmax(0,1fr)_auto] overflow-hidden">
        <IncidentHeader
          caseId={devin.caseId}
          incident={incident}
          part={part}
          sessionUrl={devin.session?.session_url ?? null}
          stubbed={devin.status === "stubbed"}
          running={devin.status === "launching"}
          onReplay={() => void startNewSession()}
          showOpenCandidates={!candidatesOpen}
          onOpenCandidates={() => setCandidatesOpen(true)}
        />
        <Conversation className="min-h-0">
          <ConversationContent
            className="mx-auto w-full max-w-3xl gap-4 px-3 py-4 sm:px-4"
            scrollClassName="chat-scrollbar overflow-x-hidden overflow-y-auto"
          >
            <SessionBanner
              status={devin.status}
              error={devin.error}
              sessionUrl={devin.session?.session_url ?? null}
            />
            <PlanChecklist
              view={cockpitView}
              launching={devin.status === "launching"}
            />
          </ConversationContent>
          <ConversationScrollButton />
        </Conversation>
        <MessageComposer
          value={message}
          state={COMPOSER_STATE}
          onChange={setMessage}
          onSend={() => undefined}
        />
      </div>
    </CockpitShell>
  );
}

function SessionBanner({
  status,
  error,
  sessionUrl,
}: {
  status: string;
  error: string | null;
  sessionUrl: string | null;
}) {
  if (status === "idle" || status === "launching") return null;
  if (status === "error") {
    return (
      <p className="text-sm text-destructive" role="alert">
        {error ?? "The API did not start a Devin session."}
      </p>
    );
  }
  if (status === "stubbed") {
    return (
      <p className="text-sm text-amber-600">
        Case is open, but Devin was stubbed. Set <code>DEVIN_API_KEY</code> on
        the API and start a new session.
        {error ? ` ${error}` : ""}
      </p>
    );
  }
  return (
    <p className="text-sm text-muted-foreground">
      Devin session is live
      {sessionUrl ? (
        <>
          {" · "}
          <a
            href={sessionUrl}
            target="_blank"
            rel="noreferrer"
            className="underline underline-offset-4"
          >
            open session
          </a>
        </>
      ) : null}
    </p>
  );
}
"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import {
  alreadyLiveDialed,
  fetchCase,
  fetchCases,
  fetchEvents,
  openCase,
  placeLiveCall,
  sessionFromEvents,
} from "@/lib/live/api";
import {
  outreachIsLive,
  pickLiveCallSupplier,
  resolveChecklist,
} from "@/lib/live/checklist";
import { EVENT_POLL_MS, HOLD_FOR, PART_ID } from "@/lib/live/config";
import { fetchPlan, type LivePlan } from "@/lib/live/plan";
import type {
  CaseEvent,
  CaseSnapshot,
  CaseSummary,
  LiveCandidate,
  OpenedCase,
  SessionInfo,
} from "@/lib/live/types";

export type DevinCaseStatus =
  "idle" | "launching" | "live" | "stubbed" | "error";

type DevinCaseState = {
  status: DevinCaseStatus;
  error: string | null;
  caseId: string | null;
  snapshot: CaseSnapshot | null;
  cases: CaseSummary[];
  events: CaseEvent[];
  plan: LivePlan | null;
  session: SessionInfo | null;
};

const EMPTY: DevinCaseState = {
  status: "idle",
  error: null,
  caseId: null,
  snapshot: null,
  cases: [],
  events: [],
  plan: null,
  session: null,
};

const EMPTY_CANDIDATES: readonly LiveCandidate[] = [];

function statusFromSession(session: SessionInfo | null): DevinCaseStatus {
  if (!session) return "live";
  return session.stubbed ? "stubbed" : "live";
}

export function useDevinCase(caseIdFromUrl: string | null) {
  const [state, setState] = useState<DevinCaseState>(EMPTY);

  const attach = useCallback(async (caseId: string, opened?: OpenedCase) => {
    const [snapshot, events, plan] = await Promise.all([
      fetchCase(caseId),
      fetchEvents(caseId),
      fetchPlan(caseId),
    ]);
    // Both reads touch the shared SQLite ERP adapter. Keep them serialized;
    // concurrent use of that connection raises sqlite3.InterfaceError.
    const cases = await fetchCases();
    const session =
      opened !== undefined
        ? {
            session_id: opened.session_id,
            session_url: opened.session_url,
            stubbed: opened.stubbed,
            error: opened.session_error,
          }
        : sessionFromEvents(events);
    setState({
      status: statusFromSession(session),
      error: session?.error ?? null,
      caseId,
      snapshot,
      cases,
      events,
      plan,
      session,
    });
  }, []);

  const launch = useCallback(async () => {
    setState({ ...EMPTY, status: "launching" });
    try {
      const opened = await openCase(PART_ID);
      await attach(opened.case_id, opened);
      return opened.case_id;
    } catch (cause) {
      const message =
        cause instanceof Error ? cause.message : "Could not open a case";
      setState({ ...EMPTY, status: "error", error: message });
      return null;
    }
  }, [attach]);

  useEffect(() => {
    if (!caseIdFromUrl) return;
    let cancelled = false;

    const load = async () => {
      try {
        await attach(caseIdFromUrl);
      } catch (cause) {
        if (cancelled) return;
        const message =
          cause instanceof Error ? cause.message : "Could not load the case";
        setState({ ...EMPTY, status: "error", error: message });
      }
    };

    void load();
    return () => {
      cancelled = true;
    };
  }, [attach, caseIdFromUrl]);

  const eventsRef = useRef<CaseEvent[]>([]);
  useEffect(() => {
    eventsRef.current = state.events;
  }, [state.events]);

  useEffect(() => {
    const caseId = state.caseId;
    if (!caseId || state.status === "error" || state.status === "launching") {
      return;
    }
    let cancelled = false;

    const tick = async () => {
      try {
        const since = eventsRef.current.at(-1)?.seq ?? 0;
        const [snapshot, fresh, plan] = await Promise.all([
          fetchCase(caseId),
          fetchEvents(caseId, since),
          fetchPlan(caseId),
        ]);
        const cases = await fetchCases();
        if (cancelled) return;
        setState((current) => {
          if (current.caseId !== caseId) return current;
          const events =
            fresh.length > 0 ? [...current.events, ...fresh] : current.events;
          const session = sessionFromEvents(events) ?? current.session;
          return {
            ...current,
            snapshot,
            cases,
            events,
            plan,
            session,
            status: statusFromSession(session),
            error: session?.error ?? current.error,
          };
        });
      } catch {
        // Keep the last good feed. The next tick retries.
      }
    };

    const interval = window.setInterval(() => void tick(), EVENT_POLL_MS);
    return () => {
      cancelled = true;
      window.clearInterval(interval);
    };
  }, [state.caseId, state.status]);

  const candidates: readonly LiveCandidate[] =
    state.snapshot?.candidates ?? EMPTY_CANDIDATES;
  const checklist = state.plan
    ? resolveChecklist(state.plan, candidates)
    : null;

  useEffect(() => {
    const caseId = state.caseId;
    if (!caseId || !checklist) return;
    if (!outreachIsLive(checklist)) return;
    if (alreadyLiveDialed(state.events)) return;
    const supplierRef = pickLiveCallSupplier(checklist, candidates, HOLD_FOR);
    if (!supplierRef) return;
    void placeLiveCall(caseId, supplierRef).catch((cause) => {
      const message =
        cause instanceof Error ? cause.message : "Live call failed";
      setState((current) =>
        current.caseId === caseId ? { ...current, error: message } : current,
      );
    });
  }, [candidates, checklist, state.caseId, state.events]);

  return {
    ...state,
    candidates,
    checklist,
    launch,
    running: state.status === "launching" || state.status === "live",
  };
}
const DELAYS_MS = [200, 100, 200, 100, 0, 100, 200, 100, 200]

export function DotLoader({
  className
}: {
  className?: string
}) {
  return (
    <span
      role="status"
      aria-label="Working"
      className={`inline-grid size-3.5 shrink-0 grid-cols-3 grid-rows-3 place-items-center ${className || 'text-foreground'}`}
    >
      {DELAYS_MS.map((delay, index) => (
        <span
          key={index}
          className="size-[2.5px] rounded-full bg-current motion-safe:animate-pulse"
          style={{ animationDelay: `${delay}ms`, animationDuration: "900ms" }}
        />
      ))}
    </span>
  )
}
import { cn } from "@/lib/utils"
import { Loader2Icon } from "@/components/icons"

function Spinner({ className, ...props }: React.ComponentProps<"svg">) {
  return (
    <Loader2Icon data-slot="spinner" role="status" aria-label="Loading" className={cn("size-4 animate-spin", className)} {...props} />
  )
}

export { Spinner }
"use client";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import type { UIMessage } from "ai";
import { ArrowDownIcon, DownloadIcon } from "@/components/icons";
import type { ComponentProps } from "react";
import { useCallback } from "react";
import { StickToBottom, useStickToBottomContext } from "use-stick-to-bottom";

export type ConversationProps = ComponentProps<typeof StickToBottom>;

export const Conversation = ({ className, ...props }: ConversationProps) => (
  <StickToBottom
    className={cn("relative flex-1 overflow-y-hidden", className)}
    initial="smooth"
    resize="smooth"
    role="log"
    {...props}
  />
);

export type ConversationContentProps = ComponentProps<
  typeof StickToBottom.Content
>;

export const ConversationContent = ({
  className,
  ...props
}: ConversationContentProps) => (
  <StickToBottom.Content
    className={cn("flex flex-col gap-8 p-4", className)}
    {...props}
  />
);

export type ConversationEmptyStateProps = ComponentProps<"div"> & {
  title?: string;
  description?: string;
  icon?: React.ReactNode;
};

export const ConversationEmptyState = ({
  className,
  title = "No messages yet",
  description = "Start a conversation to see messages here",
  icon,
  children,
  ...props
}: ConversationEmptyStateProps) => (
  <div
    className={cn(
      "flex size-full flex-col items-center justify-center gap-3 p-8 text-center",
      className
    )}
    {...props}
  >
    {children ?? (
      <>
        {icon && <div className="text-muted-foreground">{icon}</div>}
        <div className="space-y-1">
          <h3 className="font-medium text-sm">{title}</h3>
          {description && (
            <p className="text-muted-foreground text-sm">{description}</p>
          )}
        </div>
      </>
    )}
  </div>
);

export type ConversationScrollButtonProps = ComponentProps<typeof Button>;

export const ConversationScrollButton = ({
  className,
  ...props
}: ConversationScrollButtonProps) => {
  const { isAtBottom, scrollToBottom } = useStickToBottomContext();

  const handleScrollToBottom = useCallback(() => {
    scrollToBottom();
  }, [scrollToBottom]);

  return (
    !isAtBottom && (
      <Button
        className={cn(
          "absolute bottom-4 left-[50%] translate-x-[-50%] rounded-full dark:bg-background dark:hover:bg-muted",
          className
        )}
        onClick={handleScrollToBottom}
        size="icon"
        type="button"
        variant="outline"
        {...props}
      >
        <ArrowDownIcon className="size-4" />
      </Button>
    )
  );
};

const getMessageText = (message: UIMessage): string =>
  message.parts
    .filter((part) => part.type === "text")
    .map((part) => part.text)
    .join("");

export type ConversationDownloadProps = Omit<
  ComponentProps<typeof Button>,
  "onClick"
> & {
  messages: UIMessage[];
  filename?: string;
  formatMessage?: (message: UIMessage, index: number) => string;
};

const defaultFormatMessage = (message: UIMessage): string => {
  const roleLabel =
    message.role.charAt(0).toUpperCase() + message.role.slice(1);
  return `**${roleLabel}:** ${getMessageText(message)}`;
};

export const messagesToMarkdown = (
  messages: UIMessage[],
  formatMessage: (
    message: UIMessage,
    index: number
  ) => string = defaultFormatMessage
): string => messages.map((msg, i) => formatMessage(msg, i)).join("\n\n");

export const ConversationDownload = ({
  messages,
  filename = "conversation.md",
  formatMessage = defaultFormatMessage,
  className,
  children,
  ...props
}: ConversationDownloadProps) => {
  const handleDownload = useCallback(() => {
    const markdown = messagesToMarkdown(messages, formatMessage);
    const blob = new Blob([markdown], { type: "text/markdown" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = filename;
    document.body.append(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
  }, [messages, filename, formatMessage]);

  return (
    <Button
      className={cn(
        "absolute top-4 right-4 rounded-full dark:bg-background dark:hover:bg-muted",
        className
      )}
      onClick={handleDownload}
      size="icon"
      type="button"
      variant="outline"
      {...props}
    >
      {children ?? <DownloadIcon className="size-4" />}
    </Button>
  );
};
