};

export function buildCockpitView(
  snapshot: CaseSnapshot | null,
  plan: LivePlan | null,
  events: readonly CaseEvent[],
): CockpitView {
  if (!plan) return { sections: [] };

  const candidateByRef = new Map(
    snapshot?.candidates.map((candidate) => [
      candidate.supplier_ref,
      candidate,
    ]),
  );
  const recordByRef = new Map(
    snapshot?.supplier_records.map((record) => [record.supplier_id, record]),
  );
  const taskByRef = new Map(
    snapshot?.outreach_tasks.map((task) => [task.supplier_ref, task]),
  );
  const claimByRef = new Map(
    snapshot?.claims.map((claim) => [claim.supplier_ref, claim]),
  );
  const latestEventByRef = new Map<string, CaseEvent>();
  for (const event of events) {
    const supplierRef = event.payload.supplier_ref;
    if (typeof supplierRef === "string") {
      latestEventByRef.set(supplierRef, event);
    }
  }

  const sections = plan.sections.flatMap((section) => {
    const items = section.steps
      .filter((step) => step.status !== "pending")
      .map((step): CockpitViewItem => {
        if (section.group === "outreach" && step.supplier_ref) {
          const supplierRef = step.supplier_ref;
          const candidate = candidateByRef.get(supplierRef);
          const record = recordByRef.get(supplierRef);
          const task = taskByRef.get(supplierRef);
          const claim = claimByRef.get(supplierRef);
          const event = latestEventByRef.get(supplierRef);

          return {
            kind: "call",
            id: step.step_id,
            supplierRef,
            supplierName:
              candidate?.supplier_name ??
              record?.supplier_name ??
              step.label.replace(/^Calling\s+/, ""),
            status: step.status,
            taskId: task?.task_id ?? claim?.task_id ?? null,
            phoneMasked: record?.phone_masked ?? null,
            startedAt: step.started_at,
            completedAt: step.completed_at,
            detail: event?.message ?? step.detail,
            claim: claim ? buildClaimView(claim) : null,
          };
        }

        return {
          kind: "step",
          id: step.step_id,
          label: step.label,
          status: step.status,
          detail: step.detail,
          startedAt: step.started_at,
          completedAt: step.completed_at,
        };
      });

    if (items.length === 0) return [];

    return [
      {
        group: section.group,
        label: section.label,
        status: section.status ?? "pending",
        defaultOpen:
          section.status === "active" ||
          items.some((item) => item.id === plan.active_step_id),
        items,
      },
    ];
  });

  return { sections };
}

function buildClaimView(claim: Claim): CockpitClaimView {
  return {
    available: claim.available,
    quantityOffered: claim.qty_offered,
    unitPrice: claim.unit_price
      ? { amount: claim.unit_price, currency: claim.currency }
      : null,
    priceBreaks: claim.price_breaks.map((priceBreak) => ({
      minQty: priceBreak.min_qty,
      unitPrice: priceBreak.unit_price,
    })),
    moq: claim.moq,
    leadTimeDays: claim.lead_time_days,
    earliestReady: textOrNull(claim.earliest_ready_text),
    incoterm: claim.incoterm,
    paymentTerms: claim.payment_terms,
    stockStatus: claim.stock_status,
    priceQuoted: claim.price_quoted,
    partNumberConfirmed: claim.part_number_confirmed,
    certificationCurrent: claim.certification_current,
    confidence: claim.confidence,
    summary: textOrNull(claim.summary),
    evidence: [...claim.evidence],
    transcript: claim.transcript.map((turn) => ({
      offsetSeconds: turn.offset_seconds,
      speaker: turn.speaker,
      text: turn.text,
    })),
    transcriptUrl: claim.transcript_url,
    recordingUrl: claim.recording_url,
  };
}

function textOrNull(value: string): string | null {
  const text = value.trim();
  return text ? text : null;
}
import { API_BASE } from "@/lib/live/config";
import type {
  CaseEvent,
  CaseSnapshot,
  CaseSummary,
  OpenedCase,
  SessionInfo,
} from "@/lib/live/types";

let inFlightOpen: Promise<OpenedCase> | null = null;

async function readError(
  response: Response,
  fallback: string,
): Promise<string> {
  try {
    const body = (await response.json()) as { detail?: string };
    return body.detail ?? fallback;
  } catch {
    return fallback;
  }
}

export async function openCase(partId: string): Promise<OpenedCase> {
  if (inFlightOpen) return inFlightOpen;
  inFlightOpen = (async () => {
    const response = await fetch(`${API_BASE}/cases`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ part_id: partId }),
      cache: "no-store",
    });
    if (!response.ok) {
      throw new Error(
        await readError(response, `POST /cases -> ${response.status}`),
      );
    }
    return (await response.json()) as OpenedCase;
  })().finally(() => {
    inFlightOpen = null;
  });
  return inFlightOpen;
}

export async function fetchCase(caseId: string): Promise<CaseSnapshot | null> {
  const response = await fetch(
    `${API_BASE}/cases/${encodeURIComponent(caseId)}`,
    { cache: "no-store" },
  );
  if (response.status === 404) return null;
  if (!response.ok) {
    throw new Error(
      await readError(response, `GET /cases/${caseId} -> ${response.status}`),
    );
  }
  return (await response.json()) as CaseSnapshot;
}

export async function fetchCases(): Promise<CaseSummary[]> {
  const response = await fetch(`${API_BASE}/cases`, { cache: "no-store" });
  if (!response.ok) {
    throw new Error(
      await readError(response, `GET /cases -> ${response.status}`),
    );
  }
  return (await response.json()) as CaseSummary[];
}

export async function fetchEvents(
  caseId: string,
  since = 0,
): Promise<CaseEvent[]> {
  const response = await fetch(
    `${API_BASE}/cases/${encodeURIComponent(caseId)}/events?since=${since}`,
    { cache: "no-store" },
  );
  if (!response.ok) {
    throw new Error(
      await readError(
        response,
        `GET /cases/${caseId}/events -> ${response.status}`,
      ),
    );
  }
  return (await response.json()) as CaseEvent[];
}

const dialedCases = new Set<string>();
const dialing = new Set<string>();

export function alreadyLiveDialed(events: CaseEvent[]): boolean {
  return events.some((event) => event.payload.live === true);
}

/** One live CALL-E dial. Every supplier number is overridden by DEMO_CALL_DESTINATION. */
export async function placeLiveCall(
  caseId: string,
  supplierRef: string,
): Promise<void> {
  if (dialedCases.has(caseId) || dialing.has(caseId)) return;
  dialing.add(caseId);
  try {
    const query = new URLSearchParams({
      case_id: caseId,
      supplier_ref: supplierRef,
      live: "true",
    });
    const response = await fetch(`${API_BASE}/flow/call?${query}`, {
      method: "POST",
      cache: "no-store",
    });
    if (!response.ok) {
      dialedCases.add(caseId);
      throw new Error(
        await readError(response, `POST /flow/call -> ${response.status}`),
      );
    }
    dialedCases.add(caseId);
  } finally {
    dialing.delete(caseId);
  }
}

export function sessionFromEvents(events: CaseEvent[]): SessionInfo | null {
  for (let index = events.length - 1; index >= 0; index -= 1) {
    const payload = events[index].payload;
    if (typeof payload.session_url !== "string") continue;
    return {
      session_id:
        typeof payload.session_id === "string" ? payload.session_id : null,
      session_url: payload.session_url,
      stubbed: payload.stubbed === true,
      error: typeof payload.error === "string" ? payload.error : null,
    };
