"""The to-do list the cockpit renders and the agent ticks off.

The screen has to be laid out before anything runs, so the eight section headers
are fixed and always present in the same order. What is *not* fixed is how much
work happens inside them: the agent decides how many suppliers it researches and
how many it calls, and each of those becomes a step it creates at run time.

So there are two kinds of step:

- **seeded** — the eight sections' own steps, written when the case opens, all
  `pending`. They never disappear, so the checklist looks the same on every case.
- **dynamic** — `outreach:SUP-KBY`, `research:SUP-RUL`, … created by whoever is
  driving (the deterministic conductor or a Devin session) via `upsert`.

`step_id` is the identity: calling `upsert` twice with the same id moves the
existing line rather than adding a second one, which is what makes this safe for
an agent that retries. Nothing here judges whether a step *should* exist; the
plan is a display of intent, and the case artifacts remain the source of truth.
"""

from __future__ import annotations

from datetime import datetime, timezone

from backend.casestore.case_store import CaseStore
from packages.contracts.enums import PlanGroup, StepStatus
from packages.contracts.models import CasePlan, PlanSection, PlanStep

SECTION_LABELS: dict[PlanGroup, str] = {
    PlanGroup.INTAKE: "Reading the incident",
    PlanGroup.ERP: "Pulling part data",
    PlanGroup.SUPPLIERS: "Finding registered suppliers",
    PlanGroup.SCREENING: "Screening against procurement policy",
    PlanGroup.OUTREACH: "Calling suppliers",
    PlanGroup.CLAIMS: "Collecting answers",
    PlanGroup.COSTING: "Pricing every option",
    PlanGroup.REVIEW: "Handing a ranked shortlist to the buyer",
}

SECTION_ORDER: tuple[PlanGroup, ...] = tuple(SECTION_LABELS)

# The steps that exist on every case, in order. Labels are what the audience
# reads, so they are written as statements of work, not as function names.
SEEDED_STEPS: tuple[tuple[PlanGroup, str, str], ...] = (
    (PlanGroup.INTAKE, "intake:incident", "Reading the shortage the ERP raised"),
    (PlanGroup.ERP, "erp:part", "Pulling the part record, spec, weight and HS code"),
    (PlanGroup.ERP, "erp:stock", "Reading on-hand stock, reservations and take rate"),
    (PlanGroup.ERP, "erp:open_pos", "Checking open purchase orders for a delivery"),
    (PlanGroup.ERP, "erp:price_history", "Reading what we paid for it before"),
    (PlanGroup.SUPPLIERS, "suppliers:list", "Listing the approved suppliers for this part"),
    (PlanGroup.SCREENING, "screening:policy", "Applying the procurement policy to each supplier"),
    (PlanGroup.OUTREACH, "outreach:brief", "Writing the call brief"),
    (PlanGroup.CLAIMS, "claims:normalise", "Turning every answer into a structured claim"),
    (PlanGroup.COSTING, "costing:landed", "Costing single-source and split plans"),
    (PlanGroup.REVIEW, "review:package", "Writing the review package for a buyer"),
)

PLAN_FILE = "plan.json"


def _now() -> datetime:
    return datetime.now(tz=timezone.utc)


def seed(case_id: str, cases: CaseStore) -> CasePlan:
    """Write the fixed checklist. Never clobbers a plan that already has progress."""
    existing = cases.read_plan_steps(case_id)
    if existing:
        return read(case_id, cases)
    return reset(case_id, cases)


def reset(case_id: str, cases: CaseStore) -> CasePlan:
    """A fresh checklist: every fixed step pending again, dynamic steps dropped.

    A re-run replaces the plan rather than appending to it, so the cockpit shows
    one run's progress and not the remains of the previous one.
    """
    steps = [
        PlanStep(
            step_id=step_id,
            case_id=case_id,
            group=group,
            label=label,
            status=StepStatus.PENDING,
            seq=index,
        )
        for index, (group, step_id, label) in enumerate(SEEDED_STEPS)
    ]
    cases.write_plan_steps(case_id, steps)
    return read(case_id, cases)


def upsert(
    case_id: str,
    cases: CaseStore,
    *,
    step_id: str,
    group: PlanGroup | None = None,
    label: str | None = None,
    status: StepStatus | None = None,
    detail: str | None = None,
    supplier_ref: str | None = None,
) -> PlanStep:
    """Create or move one step. Timestamps are set here, not by the caller."""
    steps = cases.read_plan_steps(case_id)
    by_id = {step.step_id: step for step in steps}
    current = by_id.get(step_id)

    if current is None:
        if group is None or label is None:
            raise ValueError(f"new step {step_id} needs a group and a label")
        current = PlanStep(
            step_id=step_id,
            case_id=case_id,
            group=group,
            label=label,
            dynamic=True,
            seq=100 + len([s for s in steps if s.group == group]),
        )
        steps.append(current)

    updated = current.model_copy(
        update={
            "label": label or current.label,
            "group": group or current.group,
            "detail": detail if detail is not None else current.detail,
            "supplier_ref": supplier_ref or current.supplier_ref,
            "status": status or current.status,
        }
    )
    if updated.status is StepStatus.ACTIVE and updated.started_at is None:
        updated = updated.model_copy(update={"started_at": _now()})
    if updated.status in (StepStatus.DONE, StepStatus.FAILED, StepStatus.SKIPPED):
        updated = updated.model_copy(
            update={
                "started_at": updated.started_at or _now(),
                "completed_at": updated.completed_at or _now(),
            }
        )

    steps = [updated if s.step_id == step_id else s for s in steps]
    if updated.step_id not in {s.step_id for s in steps}:
        steps.append(updated)
    cases.write_plan_steps(case_id, steps)
    return updated


def advance(
    case_id: str,
    cases: CaseStore,
    *,
    step_id: str,
    status: StepStatus,
    detail: str | None = None,
) -> PlanStep | None:
    """Move a step that is expected to exist. A typo must not invent a line."""
    if step_id not in {s.step_id for s in cases.read_plan_steps(case_id)}:
        return None
    return upsert(case_id, cases, step_id=step_id, status=status, detail=detail)


def _section_status(steps: list[PlanStep]) -> StepStatus:
    if not steps:
        return StepStatus.PENDING
    if any(s.status is StepStatus.ACTIVE for s in steps):
        return StepStatus.ACTIVE
    if any(s.status is StepStatus.FAILED for s in steps):
        return StepStatus.FAILED
    if all(s.status in (StepStatus.DONE, StepStatus.SKIPPED) for s in steps):
        return StepStatus.DONE
    if any(s.status is StepStatus.DONE for s in steps):
        return StepStatus.ACTIVE  # part of the section is behind us
    return StepStatus.PENDING


def read(case_id: str, cases: CaseStore) -> CasePlan:
    """The checklist, grouped and ordered, with the section states derived."""
    steps = cases.read_plan_steps(case_id)
    sections: list[PlanSection] = []
    for group in SECTION_ORDER:
        in_group = sorted(
            (s for s in steps if s.group is group),
            key=lambda s: (s.seq, s.step_id),
        )
        sections.append(
            PlanSection(
                group=group,
                label=SECTION_LABELS[group],
                status=_section_status(in_group),
                steps=in_group,
            )
        )

    active = next((s.step_id for s in steps if s.status is StepStatus.ACTIVE), None)
    stamps = [s.completed_at or s.started_at for s in steps if s.completed_at or s.started_at]
    return CasePlan(
        case_id=case_id,
        sections=sections,
        active_step_id=active,
        updated_at=max(stamps) if stamps else None,
        done=len([s for s in steps if s.status in (StepStatus.DONE, StepStatus.SKIPPED)]),
        total=len(steps),
    )


def supplier_step_id(group: PlanGroup, supplier_ref: str) -> str:
    """`outreach:SUP-KBY`. One id per supplier per group, so retries are idempotent."""
    return f"{group.value}:{supplier_ref}"
"""Start the Devin session that works the case.

The session gets the case id and the base URL of this API, and is told to read
the part out of the ERP before it looks at suppliers — that order is the story:
specs first, then who can make them.

Without `DEVIN_API_KEY` this returns a stub session and says so. A missing key
must never be the reason a demo stops, and it must never be mistaken for a real
run either, which is why `stubbed` is on the response and in the event payload.
"""

from __future__ import annotations

import os
from dataclasses import dataclass
from datetime import datetime, timezone

import httpx

from packages.contracts.models import Incident, Part

DEFAULT_API_BASE = "https://api.devin.ai"

# A sourcing case is a dozen HTTP calls, not an engineering task. The cap is the
# only hard stop on a session that decides to go exploring, so it is low on
# purpose and overridable for a longer run.
DEFAULT_MAX_ACU = 20


@dataclass(frozen=True)
class DevinSession:
    session_id: str
    session_url: str
    stubbed: bool
    error: str | None = None


def session_prompt(incident: Incident, part: Part, base_url: str) -> str:
    """What the session is told. Explicit, ordered, and no human to ask."""
    base = base_url.rstrip("/")
    return "\n".join(
        [
            f"You are sourcing case {incident.case_id} for Meridian Motors. Work it to the end;"
            " there is nobody to ask.",
            "",
            f"Shortage: part {incident.part_id} ({part.item_code}, {part.item_name}) at"
            f" {incident.plant_id}/{incident.production_line}. {incident.qty_required:,} needed by"
            f" {incident.needed_by}, {incident.qty_on_hand:,} on hand, so short"
            f" {incident.shortfall:,}. Line stops {incident.line_stop_at.isoformat()} at"
            f" EUR {incident.line_stop_cost_per_hour}/hour.",
            f"Why: {incident.reason}" if incident.reason else "",
            "",
            f"The ERP and the case live behind {base}. In this order:",
            f"1. GET {base}/tools/part/{incident.part_id} — the full spec, weight, HS code and"
            " criticality. Also GET /tools/stock, /tools/open_pos and /tools/price_history for it.",
            f"2. GET {base}/tools/suppliers?part_id={incident.part_id} — the approved suppliers.",
            f"3. POST {base}/tools/screen?case_id={incident.case_id} — screen them against company"
            " policy. Rejections cite the rule; do not argue with them.",
            f"4. POST {base}/tools/outreach?case_id={incident.case_id} — ask the compliant ones."
            f" Then POST {base}/tools/claims to file what each one said. Unknown stays unknown.",
            f"5. POST {base}/tools/decide?case_id={incident.case_id} — price every single-source and"
            " split plan, then POST /tools/publish_pr to file the review package.",
            "",
            "",
            "The cockpit shows a checklist, and a step nobody ticks reads as you being stuck"
            " there. Keep it current — this is not optional narration, it is the only thing the"
            " human watching can see:",
            f"- POST {base}/tools/plan/step?case_id={incident.case_id}&step_id=...&status=active"
            " before you start a step, and the same call with status=done (or failed) after it,"
            " optionally with &detail=<one short human sentence>.",
            "- The steps that already exist, in order: intake:incident, erp:part, erp:stock,"
            " erp:open_pos, erp:price_history, suppliers:list, screening:policy, outreach:brief,"
            " claims:normalise, costing:landed, review:package. Use those ids exactly.",
            "- How many suppliers you research and call is your decision, so those steps do not"
            " exist yet: create one per supplier with step_id=screening:<SUPPLIER_REF> or"
            " outreach:<SUPPLIER_REF>, group=screening or outreach, label=\"Screening Kugellager"
            " Bayern\" / \"Calling Rulmenti\" (the supplier's real name, it is on screen), and"
            " supplier_ref=<SUPPLIER_REF>.",
            f"- Calling several suppliers at once: POST {base}/tools/plan/steps?case_id="
            f"{incident.case_id} with a JSON list of those objects, so they appear together.",
            "- Repeating a step_id updates that line; it never creates a second one.",
            f"- Anything worth saying that is not a step transition goes to POST {base}/tools/events"
            " (case_id, stage, message). One line, no internal detail.",
            "",
            "Bounds, all of them hard:",
            f"- Never call POST {base}/cases. That human-only endpoint launches another Devin"
            " session recursively. This case already exists; use only its id and the tool"
            " endpoints listed above.",
            "- This is a procurement case. It is not a coding task: do not read, write or refactor"
            " repository source code, do not run test suites, do not open a GitHub pull request"
            f" yourself \u2014 the review package is filed only by POST {base}/tools/publish_pr, and by"
            " nothing else",
            "- Use only the endpoints named above. No other tool, host, browser or shell.",
            "- Do not dial anyone yourself. Calling is the backend's job and is rehearsed unless live"
            " calling is switched on there.",
            "- You do not place the order and you do not pick the winner — present the ranked options"
            " with landed cost and arrival date so a buyer decides.",
            "- Never invent a supplier answer. A field a call did not establish stays unknown.",
            "- If an endpoint fails twice, post the failure as an event and carry on with the rest of"
            " the case. Do not debug the backend.",
            f"- Stop when {base}/cases/{incident.case_id} shows the ranked options and the review"
            " package. Do not wait for a human.",
        ]
    ).replace("\n\n\n", "\n\n")


def _max_acu() -> int:
    raw = os.environ.get("DEVIN_MAX_ACU", "").strip()
    try:
        return max(1, int(raw)) if raw else DEFAULT_MAX_ACU
    except ValueError:
        return DEFAULT_MAX_ACU


def _stub(incident: Incident, error: str | None = None) -> DevinSession:
    stamp = int(datetime.now(tz=timezone.utc).timestamp())
    session_id = f"devin-stub-{incident.case_id.lower()}-{stamp}"
    return DevinSession(
        session_id=session_id,
        session_url=f"https://app.devin.ai/sessions/{session_id}",
        stubbed=True,
        error=error,
    )


def start_session(incident: Incident, part: Part, base_url: str) -> DevinSession:
    """POST a session to the Devin API, or return a stub if we cannot."""
    api_key = os.environ.get("DEVIN_API_KEY", "").strip()
    if not api_key:
        return _stub(incident)

    api_base = os.environ.get("DEVIN_API_BASE_URL", DEFAULT_API_BASE).rstrip("/")
    try:
        response = httpx.post(
            f"{api_base}/v1/sessions",
            headers={"Authorization": f"Bearer {api_key}"},
            json={
                "prompt": session_prompt(incident, part, base_url),
                "title": f"Sourcing {incident.case_id} ({part.item_code})",
                "tags": ["supplyguard", incident.case_id],
                # Nothing in a sourcing case needs a credential or an
                # organisation's knowledge base, so it gets neither: the smallest
                # blast radius a session can be started with.
                "secret_ids": [],
                "knowledge_ids": [],
                "max_acu_limit": _max_acu(),
            },
            timeout=30.0,
        )
    except httpx.HTTPError as error:
        return _stub(incident, f"could not reach {api_base}: {error}")

    if response.status_code >= 400:
        return _stub(incident, f"Devin API {response.status_code}: {response.text[:200]}")

    body = response.json()
    session_id = str(body.get("session_id", "")) or "unknown"
    return DevinSession(
        session_id=session_id,
        session_url=str(body.get("url") or f"https://app.devin.ai/sessions/{session_id}"),
        stubbed=False,
    )
